from loader import pack, normalize_key, chunk, ALPHABET


def test_normalize_key_lowercases_and_collapses():
    assert normalize_key("  Foo  Bar baz ") == "foo_bar_baz"


def test_normalize_key_empty():
    assert normalize_key("") == ""


